<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import AppLayout from '@/layouts/AppLayout.vue';
import { create, index, show } from '@/routes/rostering/requests';
type RequestRow = { identifier: string; doctor: { identifier: string; name: string }; period: { identifier: string; title: string }; request_type: string; status: string; dates: string[]; conflicted: boolean };
type Option = { identifier: string; title?: string; full_name?: string };
const props = defineProps<{ requests: RequestRow[]; periods: Option[]; doctors: Option[]; filters: Record<string, string> }>();
function filter(key: string, value: string) {
 router.get(index(), { ...props.filters, [key]: value || undefined }, { preserveState: true });
}
</script>
<template><Head title="Schedule requests" /><AppLayout :breadcrumbs="[{ title: 'Rostering', href: '/rostering' }, { title: 'Requests', href: index() }]"><main class="flex flex-col gap-6 p-4 md:p-6"><header class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-sm text-muted-foreground">Administrator-entered operational inputs</p><h1 class="text-2xl font-semibold">Doctor schedule requests</h1></div><Link :href="create()" class="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Record request</Link></header><section class="grid gap-3 rounded-lg border p-4 sm:grid-cols-3 lg:grid-cols-6"><select class="rounded-md border bg-background p-2" :value="filters.period" @change="filter('period', ($event.target as HTMLSelectElement).value)"><option value="">All periods</option><option v-for="p in periods" :key="p.identifier" :value="p.identifier">{{ p.title }}</option></select><select class="rounded-md border bg-background p-2" :value="filters.doctor" @change="filter('doctor', ($event.target as HTMLSelectElement).value)"><option value="">All doctors</option><option v-for="d in doctors" :key="d.identifier" :value="d.identifier">{{ d.full_name }}</option></select><select class="rounded-md border bg-background p-2" :value="filters.type" @change="filter('type', ($event.target as HTMLSelectElement).value)"><option value="">All types</option><option v-for="type in ['available','unavailable','leave','preferred_work','preferred_off']" :key="type">{{ type }}</option></select><select class="rounded-md border bg-background p-2" :value="filters.status" @change="filter('status', ($event.target as HTMLSelectElement).value)"><option value="">All statuses</option><option v-for="status in ['submitted','accepted','rejected','withdrawn']" :key="status">{{ status }}</option></select><input class="rounded-md border bg-background p-2" type="date" :value="filters.date" aria-label="Filter by date" @change="filter('date', ($event.target as HTMLInputElement).value)" /><select class="rounded-md border bg-background p-2" :value="filters.conflict" @change="filter('conflict', ($event.target as HTMLSelectElement).value)"><option value="">All conflict states</option><option value="yes">With conflict</option><option value="no">Without conflict</option></select></section><div class="overflow-x-auto rounded-lg border"><table class="w-full text-left text-sm"><thead class="bg-muted/50"><tr><th class="p-3">Doctor</th><th class="p-3">Request</th><th class="p-3">Dates</th><th class="p-3">Status</th><th class="p-3">Conflict</th></tr></thead><tbody><tr v-for="item in requests" :key="item.identifier" class="border-t"><td class="p-3"><Link :href="show(item.identifier)" class="font-medium underline-offset-4 hover:underline">{{ item.doctor.name }}</Link><p class="text-xs text-muted-foreground">{{ item.identifier }}</p></td><td class="p-3">{{ item.request_type.replaceAll('_',' ') }}</td><td class="p-3">{{ item.dates.join(', ') }}</td><td class="p-3">{{ item.status }}</td><td class="p-3"><span v-if="item.conflicted" class="rounded bg-amber-100 px-2 py-1 text-amber-900">Review</span><span v-else>None</span></td></tr></tbody></table></div></main></AppLayout></template>
